    ExaModels.@add_con(c, d.c01*x[d.x01] + d.c02*x[d.x02] + d.c03*x[d.x03] + d.c04*x[d.x04] + d.c05*x[d.x05] + d.c06*x[d.x06] + d.c07*x[d.x07] + d.c08*x[d.x08] + d.c09*x[d.x09] + d.c10*x[d.x10] + d.c11*x[d.x11] + d.c12*x[d.x12] + d.c13*x[d.x13] + d.c14*x[d.x14] + d.c15*x[d.x15] + d.c16*x[d.x16] + d.c17*x[d.x17] + d.c18*x[d.x18] - d.rhs for d in data_L_b3; lcon = T(-Inf), ucon = T(0.0))
    return ExaModels.ExaModel(c; kwargs...)
end
